mapper.select:
with -- 第一个 CTE：从账户辅助余额表获取期初估算余额 account_assist_balance as ( select t.contract_code, t.org_id, coalesce(t.month_end_credit_balance, 0) - coalesce(t.month_end_debit_balance, 0) as payable_insurance_estimate_balance_opening, 0 as payable_insurance_estimate_amount_debit, 0 as payable_insurance_estimate_amount_credit, 0 as payable_insurance_balance_actual, 0 as payable_insurance_balance_lease, 0 as payable_insurance_balance_structure, 0 as payable_insurance_balance_withdrawal from eg_account_assist_balance t where t.del_flag = '0' and t.account_code = #{param.accountCode} and t.period_code = #{param.lastPeriodCode}
and t.org_id in
#{item}
), -- 第二个 CTE：从凭证和凭证分录表获取借贷金额 voucher_transaction as ( select eve.contract_code, ev.org_id, 0 as payable_insurance_estimate_balance_opening, eve.debit_amount as payable_insurance_estimate_amount_debit, eve.credit_amount as payable_insurance_estimate_amount_credit, 0 as payable_insurance_balance_actual, 0 as payable_insurance_balance_lease, 0 as payable_insurance_balance_structure, 0 as payable_insurance_balance_withdrawal from eg_voucher ev left join eg_voucher_entry eve on ev.id = eve.voucher_id and eve.del_flag = '0' where ev.del_flag = '0' and ev.period_code = #{param.periodCode} and eve.period_code = #{param.periodCode} and eve.account_code = #{param.accountCode}
and ev.org_id in
#{item}
), -- 第三个 CTE：根据场景代码计算实际、租赁、结构和提现余额 scene_balance as ( select eve.contract_code, ev.org_id, 0 as payable_insurance_estimate_balance_opening, 0 as payable_insurance_estimate_amount_debit, 0 as payable_insurance_estimate_amount_credit, case when ev.scene_code in ('SDFP', 'SQBXFFP') and eve.account_code = '2701.03.01' then coalesce(eve.debit_amount, 0) - coalesce(eve.credit_amount, 0) else 0 end as payable_insurance_balance_actual, case when ev.scene_code = 'HTQZ' and eve.account_code = '2701.03.01' then coalesce(eve.credit_amount, 0) - coalesce(eve.debit_amount, 0) else 0 end as payable_insurance_balance_lease, case when ev.scene_code = 'JYJGBG' and eve.account_code = '2701.03.01' then coalesce(eve.credit_amount, 0) - coalesce(eve.debit_amount, 0) else 0 end as payable_insurance_balance_structure, case when ev.scene_code = 'HTCX' and eve.account_code = '2701.03.01' then coalesce(eve.credit_amount, 0) - coalesce(eve.debit_amount, 0) else 0 end as payable_insurance_balance_withdrawal from eg_voucher ev left join eg_voucher_entry eve on ev.id = eve.voucher_id and eve.del_flag = '0' where ev.del_flag = '0' and ev.period_code = #{param.periodCode} and eve.period_code = #{param.periodCode}
and ev.org_id in
#{item}
), -- 合并三个 CTE 的结果并进行分组聚合 aggregated_data as ( select t1.org_id, t1.contract_code, sum(t1.payable_insurance_estimate_balance_opening) as payable_insurance_estimate_balance_opening, sum(t1.payable_insurance_estimate_amount_debit) as payable_insurance_estimate_amount_debit, sum(t1.payable_insurance_estimate_amount_credit) as payable_insurance_estimate_amount_credit, sum(t1.payable_insurance_estimate_balance_opening) + sum(t1.payable_insurance_estimate_amount_credit) - sum(t1.payable_insurance_estimate_amount_debit) as payable_insurance_estimate_balance_ending, sum(t1.payable_insurance_balance_actual) as payable_insurance_balance_actual, sum(t1.payable_insurance_balance_lease) as payable_insurance_balance_lease, sum(t1.payable_insurance_balance_structure) as payable_insurance_balance_structure, sum(t1.payable_insurance_balance_withdrawal) as payable_insurance_balance_withdrawal from ( select * from account_assist_balance union all select * from voucher_transaction union all select * from scene_balance ) t1 group by t1.org_id, t1.contract_code ) select -- 从聚合结果表 aggregated_data 中选取组织 ID 和合同编码 ad.org_id, ad.contract_code, -- 选取或计算应付保险相关金额 coalesce(ad.payable_insurance_estimate_balance_opening, 0) as payable_insurance_estimate_balance_opening, coalesce(ad.payable_insurance_estimate_amount_debit, 0) as payable_insurance_estimate_amount_debit, coalesce(ad.payable_insurance_estimate_amount_credit, 0) as payable_insurance_estimate_amount_credit, coalesce(ad.payable_insurance_estimate_balance_ending, 0) as payable_insurance_estimate_balance_ending, coalesce(ad.payable_insurance_balance_actual, 0) as payable_insurance_balance_actual, coalesce(ad.payable_insurance_balance_lease, 0) as payable_insurance_balance_lease, coalesce(ad.payable_insurance_balance_structure, 0) as payable_insurance_balance_structure, coalesce(ad.payable_insurance_balance_withdrawal, 0) as payable_insurance_balance_withdrawal, -- 从合同月度表中选取合同状态相关信息 c.financial_contract_status, c.contract_status, c.client_code, c.client_name from aggregated_data ad -- 通过组织 ID 和合同编码关联合同月度表 inner join eg_contract_month c on ad.org_id = c.org_id and ad.contract_code = c.contract_code
